#include <bits/stdc++.h>
using namespace std;
int t,sum;
struct node{
    int cnt,ttt[30],ans[1005];
    bool vis[1005];
    // memset(ttt, -1, sizeof(ttt));
};
int pla(char c){
    return c-'a';
}
vector<node>a(5005);
void insert(string s,int i){
    int cur=0;
    for(char c:s){
        int idx=pla(c);
        if(a[cur].ttt[idx]==-1) a[cur].ttt[idx]=sum++;
        cur=a[cur].ttt[idx];
        if(!a[cur].vis[i]){
            a[cur].cnt++;
            a[cur].ans[a[cur].cnt]=i;
            a[cur].vis[i]=1;
        }
    }
}
void query(string s){
    int cur=0;
    for (char c:s){
        int idx=pla(c);
        if(a[cur].ttt[idx]==-1)return;
        cur=a[cur].ttt[idx];
    }
    for (int i=1;i<=a[cur].cnt;i++){
        cout<<a[cur].ans[i]<<" ";
    }
}
void solve(){
    for (int i=0;i<5000;i++) {
        a[i].cnt=0;
        memset(a[i].ttt,-1,sizeof(a[i].ttt));
    }
    sum=1;
    int n,q;
    cin>>n;
    for(int i=1;i<=n;i++){
        int va;
        cin>>va;
        for(int j=1;j<=va;j++){
            string s;
            cin>>s;
            insert(s,i);
        }
    }
    cin>>q;
    for (int i=1;i<=q;i++){
        string s;
        cin>>s;
        query(s);
        cout<<endl;
    }
}
int main(){
    for (int i=0;i<1005;i++) {
        a[i].cnt=0;
        memset(a[i].ttt,-1,sizeof(a[i].ttt));
    }
    solve();
    return 0;
}

